def refs():
    return [{**s, "subject": "science", "locator": "有氧呼吸、能量釋放、氧氣／二氧化碳證據、植物與微生物及缺氧情境", "observedPattern": "公開公立學校生物資料常用運動、發芽種子、酵母產氣與氣體檢測判讀呼吸作用；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-bc-iv-2-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開生物科資料僅供呼吸作用、能量釋放、氣體證據與缺氧比較的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開公立學校生物科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "細胞進行有氧呼吸時，主要利用有機物和氧氣，產生什麼結果？", {"A": "二氧化碳、水與可供細胞使用的能量", "B": "只產生氧氣而不釋放能量", "C": "把水直接變成葡萄糖", "D": "讓有機物質量全部消失"}, "A", "有氧呼吸分解有機物，產生二氧化碳與水並釋放能量；能量會被細胞轉存、利用，選 A。", "先對照反應物與產物，再區分物質產物和可利用能量。", ["確認反應物包含有機物與氧氣。", "有機物中的化學能在分解過程中釋放。", "主要物質產物是二氧化碳與水。", "細胞把部分能量轉成可利用形式。", "所以選 A。"], "easy"),
    make(2, "跑步後肌肉需要更多能量。下列哪項最能說明呼吸作用和肌肉收縮的關係？", {"A": "呼吸作用釋放的能量可供肌肉收縮使用", "B": "肌肉收縮會把所有氧氣變成肌肉", "C": "呼吸作用只在肺部進行，肌肉不參與", "D": "肌肉收縮會停止細胞內代謝"}, "A", "肌肉細胞分解有機物釋放能量，供收縮等活動使用；肺部換氣只是取得氧氣的身體層次，不等於細胞呼吸本身，選 A。", "把器官層次的氣體交換和細胞層次的能量釋放分開。", ["跑步提高肌肉細胞的能量需求。", "肌肉細胞內可進行有機物分解。", "呼吸作用釋放的能量支援收縮。", "肺部只協助氧氣進入血液，不是能量產生場所。", "因此選 A。"], "easy"),
    make(3, "把等量發芽種子與煮沸後冷卻的種子分別放入密閉瓶，其他條件相同。若測得前者二氧化碳較多，最合理的解釋是？", {"A": "發芽種子仍活躍呼吸，煮沸種子多數細胞已失活", "B": "煮沸種子進行的光合作用較強", "C": "二氧化碳只能由水蒸發產生", "D": "發芽種子沒有進行任何代謝"}, "A", "發芽種子是活的組織，代謝時會產生二氧化碳；煮沸處理可作失活對照，選 A。", "先確認材料是否仍具有生命活動，再用對照組排除容器或水分因素。", ["兩瓶使用等量且同來源的種子。", "煮沸處理使對照材料的細胞活性大幅降低。", "發芽種子持續分解儲存養分並呼吸。", "二氧化碳增加是活性呼吸的線索。", "所以選 A。"], "medium"),
    make(4, "酵母在有糖溶液中產生氣泡。若要支持『酵母進行代謝』的說法，哪項設計最有幫助？", {"A": "設無酵母但含等量糖液的對照，並測量相同時間的氣體量", "B": "每瓶同時更換糖量、溫度與容器大小", "C": "只觀察瓶子外觀，不記錄時間", "D": "把氣泡直接當成能量數值而不作對照"}, "A", "無酵母對照可判斷氣體是否主要由酵母活動造成；固定時間與糖量才能比較，選 A。", "用對照與控制變因把『看到氣泡』轉成可檢驗的代謝證據。", ["自變因是是否加入酵母。", "糖液體積、濃度、溫度與反應時間保持一致。", "記錄各組產生的氣體量。", "若只有有酵母組明顯產氣，支持酵母代謝造成差異。", "因此選 A。"], "medium"),
    make(5, "植物白天接受光照時，關於呼吸作用的敘述何者正確？", {"A": "植物仍會呼吸，光合作用與呼吸作用可同時發生", "B": "只要有光，植物細胞就完全停止呼吸", "C": "植物只有根會呼吸，葉片不會", "D": "呼吸作用只會製造氧氣"}, "A", "植物活細胞日夜都需進行呼吸作用；有光時若能進行光合作用，兩種作用可同時發生，選 A。", "先用『生物活細胞是否需要能量』判斷，再避免把白天的光合作用誤當成呼吸停止。", ["植物細胞仍需能量維持運輸、生長與修復。", "能量可由呼吸作用釋放。", "光照只提供光合作用的條件，不會取消呼吸作用。", "葉、莖、根等活組織都可能呼吸。", "所以選 A。"], "easy"),
    make(6, "在氧氣不足時，肌肉仍可短時間維持活動但容易疲勞。這最適合解釋為？", {"A": "缺氧時能量供應方式受限，無法長時間維持高需求", "B": "缺氧會讓細胞完全不需要能量", "C": "肌肉會把二氧化碳轉成氧氣供應自己", "D": "氧氣不足會使所有呼吸作用立刻永久停止"}, "A", "氧氣不足時有氧呼吸受限制，細胞可暫時依賴效率較低的代謝途徑，但供能不易長久滿足高強度活動，選 A。", "比較有氧條件與缺氧條件的供能效率與持續時間，不把暫時補救說成完全停止。", ["高強度肌肉活動需要快速供能。", "氧氣不足會限制有氧呼吸的持續進行。", "細胞仍可能使用其他短期代謝途徑。", "這些途徑供能效率與可持續性有限。", "所以容易疲勞，選 A。"], "hard"),
    make(7, "測量發芽種子呼吸時，哪一項資料最直接顯示氧氣被消耗？", {"A": "密閉裝置內氧氣比例隨時間下降，且有適當失活對照", "B": "種子顏色變深，但沒有氣體測量", "C": "容器標籤寫著『活種子』", "D": "室內光線變亮"}, "A", "直接測得氧氣比例下降，並與失活對照比較，才能把氣體變化和種子呼吸連結，選 A。", "判讀證據時要求直接測量目標量，並確認對照能排除非生物因素。", ["題目要找的是氧氣消耗證據。", "需使用密閉裝置追蹤氧氣比例。", "失活種子對照可檢查容器本身的變化。", "活種子組較快下降才支持呼吸消耗氧氣。", "因此選 A。"], "medium"),
    make(8, "若運動後測得呼出氣體中的二氧化碳增加，下列哪個說法最嚴謹？", {"A": "可作為呼吸作用增強的線索，但仍需配合活動量與對照", "B": "只要二氧化碳增加，就能知道釋放能量的精確數值", "C": "二氧化碳增加證明肺部本身製造了葡萄糖", "D": "二氧化碳增加表示細胞停止使用氧氣"}, "A", "呼出二氧化碳增加可支持代謝活動提高，但氣體量不是能量的直接等值測量，還需控制呼氣量、時間與活動條件，選 A。", "分辨『反應線索』和『完整定量證明』，不要把單一指標過度解讀。", ["運動會改變呼吸與代謝需求。", "二氧化碳增加可反映分解有機物的活動。", "呼氣量與採樣時間也會影響測值。", "因此需要對照與其他資料才能估計能量結果。", "所以最嚴謹的敘述是 A。"], "hard"),
    make(9, "下列何者能同時說明植物與動物都會進行呼吸作用？", {"A": "兩者的活細胞都需分解有機物以取得可用能量", "B": "只有具有肺的動物和有葉綠體的植物才會呼吸", "C": "植物只能在夜間呼吸，動物只能在白天呼吸", "D": "植物製造氧氣就代表植物不需能量"}, "A", "呼吸作用是活細胞取得能量的共同代謝方式，不以肺或葉綠體的有無作為必要條件，選 A。", "從『活細胞的能量需求』判斷，而不是從外部器官或光照時段判斷。", ["列出植物與動物都具有活細胞。", "活細胞需要能量完成共同生命活動。", "有機物可在細胞內被分解並釋放能量。", "肺是動物換氣器官，葉綠體是光合作用構造，兩者都不是呼吸的限定條件。", "所以選 A。"], "easy"),
    make(10, "某研究只測到一組酵母溶液產生較多二氧化碳。下列哪項結論超出目前證據，不能直接下定論？", {"A": "酵母產生二氧化碳的同時釋放了多少能量", "B": "該組在測量時間內二氧化碳增加較多", "C": "可能有糖濃度或溫度等條件影響結果", "D": "需要檢查是否有無酵母對照"}, "A", "二氧化碳量是呼吸或發酵的線索，但不是能量的直接計量；在缺少熱量或其他能量資料時不能推出精確能量，選 A。", "把觀察到的氣體結果、可能原因與尚未測量的能量量值分開。", ["先寫出實驗直接測到的是二氧化碳。", "氣體增加可描述產物變化，但不等於能量數值。", "糖、溫度、時間與對照會影響解釋。", "要回答能量大小需另外設計能量測量。", "因此不能直接推出 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    old = {o["id"]: o["text"] for o in q["options"]}
    old_a, old_target = old["A"], old[target]
    old["A"], old[target] = old_target, old_a
    q["options"] = [{"id": k, "text": old[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A", f"選 {target}")
    q["solutionStrategy"] = q["solutionStrategy"].replace("選 A", f"選 {target}")
    q["solutionSteps"] = [s.replace("選 A", f"選 {target}").replace("所以選 A", f"所以選 {target}") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
